@Component("customerAddress-handler")
@ProcessingGroup("customerAddress-processing-group")
public class CustomerAddressEventHandler {
	
	// core constructor
	CustomerAddressEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCustomerAddressEvent
     */
    @EventHandler
    public void handle( CreateCustomerAddressEvent event) {
        entityManager.persist(new CustomerAddress(event.getCustomerAddressId(), event.getLabel(), event.getAddress(), event.getAsDefaultShipping(), event.getAsDefaultBilling(), event.getCustomer()));
    }

    /*
     * @param	event UpdateCustomerAddressEvent
     */
    @EventHandler
    public CustomerAddress handle( UpdateCustomerAddressEvent event) {
    	entityManager.merge(new CustomerAddress(event.getCustomerAddressId(), event.getLabel(), event.getAddress(), event.getAsDefaultShipping(), event.getAsDefaultBilling(), event.getCustomer()));
    }
    
    /*
     * @param	event DeleteCustomerAddressEvent
     */
    @EventHandler
    public void on( DeleteCustomerAddressEvent event) {
    	CustomerAddress entity = new CustomerAddress();
   
    	// ------------------------------------------
    	// apply the CustomerAddressId
    	// ------------------------------------------
    	entity.setCustomerAddressId( event.getCustomerAddressId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CustomerAddressRepository customerAddressEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CustomerAddressEventHandler.class.getName());

}
